import{_ as i,I as B,c as l,o as a,a3 as t,b as E,w as o,a as c,J as n,a4 as A}from"./chunks/framework.BusRvirq.js";const p=JSON.parse('{"title":"속성 기반 접근 제어(ABAC) 및 크롤링 데이터 보안 체계","description":"수집된 비정형 데이터 및 내부 에이전트 간 통신에 대한 속성 기반 접근 제어(ABAC) 아키텍처와 보안 토큰 감사 체계","frontmatter":{"title":"속성 기반 접근 제어(ABAC) 및 크롤링 데이터 보안 체계","shortTitle":"ABAC 데이터 보안","category":"런타임 안정성 & 보안","sort":11,"description":"수집된 비정형 데이터 및 내부 에이전트 간 통신에 대한 속성 기반 접근 제어(ABAC) 아키텍처와 보안 토큰 감사 체계","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/synccrawl/abac-data-security.html"}]]},"headers":[],"relativePath":"synccrawl/abac-data-security.md","filePath":"ko/synccrawl/abac-data-security.md","lastUpdated":1791239682000}'),d={name:"synccrawl/abac-data-security.md"};function s(C,e,u,D,b,h){const r=B("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="속성-기반-접근-제어-abac-및-크롤링-데이터-보안-체계" tabindex="-1">속성 기반 접근 제어(ABAC) 및 크롤링 데이터 보안 체계 <a class="header-anchor" href="#속성-기반-접근-제어-abac-및-크롤링-데이터-보안-체계" aria-label="Permalink to “속성 기반 접근 제어(ABAC) 및 크롤링 데이터 보안 체계”">​</a></h1><h2 id="_1-도입-배경-및-rbac의-한계" tabindex="-1">1. 도입 배경 및 RBAC의 한계 <a class="header-anchor" href="#_1-도입-배경-및-rbac의-한계" aria-label="Permalink to “1. 도입 배경 및 RBAC의 한계”">​</a></h2><p>전통적인 역할 기반 접근 제어(RBAC)는 사용자의 역할(<code>ROLE_USER</code>, <code>ROLE_ADMIN</code> 등)을 기준으로 API 엔드포인트의 접근 여부를 판별합니다. 그러나 수집 데이터 및 다중 에이전트가 협업하는 환경에서는 다음과 같은 복합 권한 검증에 한계가 드러납니다:</p><ol><li><strong>테넌트 및 부서별 데이터 격리 부재</strong>: 동일한 수집 담당자 역할이라도 A 사업부에서 수집한 경쟁사 분석 데이터에 B 사업부 담당자가 접근해서는 안 되는 세분화된 소유권(Data Ownership) 통제 필요.</li><li><strong>에이전트 간 통신 신뢰 체계</strong>: 백엔드 내부 워커 에이전트 간의 통신(Pod-to-Pod)이 일반 사용자 세션을 완전히 우회(Implicit Bypass)하지 않도록 명시적 토큰과 속성을 검증해야 함.</li><li><strong>네트워크 환경에 따른 동적 차단</strong>: 동일한 관리자 계정이라 할지라도 사내 내부망(VNet)이 아닌 외부 공용망에서 유입되는 특정 관리 도구 호출은 차단되어야 함.</li></ol><p><code>SyncCrawl</code>은 이를 해결하기 위해 주체, 자원, 환경의 다차원 속성을 결합 평가하는 <strong>속성 기반 접근 제어(ABAC: Attribute-Based Access Control)</strong> 아키텍처를 적용하였습니다.</p>',5)),(a(),E(A,null,{default:o(()=>[n(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Req%5B%22API%20%ED%98%B8%EC%B6%9C%20%EC%9A%94%EC%B2%AD%20(Subject%20%2B%20Resource%20%2B%20Environment)%22%5D%20--%3E%20G1%7B%221%EB%8B%A8%EA%B3%84%3A%20%ED%99%98%EA%B2%BD%20%EA%B2%8C%EC%9D%B4%ED%8A%B8%20(Deny-first)%3Cbr%2F%3E%EB%84%A4%ED%8A%B8%EC%9B%8C%ED%81%AC%20%EC%9C%84%EC%B9%98%20%2F%20%EB%B9%84%EC%9D%B8%EA%B0%80%20%EA%B2%BD%EB%A1%9C%20%EA%B2%80%EC%A6%9D%22%7D%0A%20%20%20%20G1%20--%20%22%EC%99%B8%EB%B6%80%EB%A7%9D%EC%97%90%EC%84%9C%20%EB%82%B4%EB%B6%80%20%EC%A0%84%EC%9A%A9%20%EC%97%94%EB%93%9C%ED%8F%AC%EC%9D%B8%ED%8A%B8%20%EC%A0%91%EA%B7%BC%22%20--%3E%20Deny1%5B%22%EC%A6%89%EC%8B%9C%20%EA%B1%B0%EC%A0%88%20(403%20Forbidden)%22%5D%0A%20%20%20%20G1%20--%20%22%ED%86%B5%EA%B3%BC%22%20--%3E%20G2%7B%222%EB%8B%A8%EA%B3%84%3A%20%EB%8C%80%EB%B6%84%EB%A5%98%20RBAC%20%EA%B2%80%EC%A6%9D%3Cbr%2F%3E%EA%B8%B0%EB%B3%B8%20%EC%97%AD%ED%95%A0%2F%EA%B6%8C%ED%95%9C%20%EB%B3%B4%EC%9C%A0%20%EC%97%AC%EB%B6%80%22%7D%0A%20%20%20%20G2%20--%20%22%EC%97%AD%ED%95%A0%20%EB%AF%B8%EB%B3%B4%EC%9C%A0%22%20--%3E%20Deny2%5B%22%EC%A6%89%EC%8B%9C%20%EA%B1%B0%EC%A0%88%20(403%20Forbidden)%22%5D%0A%20%20%20%20G2%20--%20%22%ED%86%B5%EA%B3%BC%22%20--%3E%20G3%7B%223%EB%8B%A8%EA%B3%84%3A%20%EC%84%B8%EB%B6%80%20ABAC%20%ED%8F%89%EA%B0%80%20(Allow-only)%3Cbr%2F%3E%EC%86%8C%EC%9C%A0%EC%9E%90%20%EC%9D%BC%EC%B9%98%20%EB%B0%8F%20%EB%B3%B4%EC%95%88%20%EB%93%B1%EA%B8%89%20%ED%8F%89%EA%B0%80%22%7D%0A%20%20%20%20G3%20--%20%22%EC%86%8D%EC%84%B1%20%EC%A1%B0%EA%B1%B4%20%EC%B6%A9%EC%A1%B1%22%20--%3E%20Allow%5B%22%EC%9A%94%EC%B2%AD%20%EC%9D%B8%EA%B0%80%20%EB%B0%8F%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EB%B0%98%ED%99%98%22%5D%0A%20%20%20%20G3%20--%20%22%EC%86%8D%EC%84%B1%20%EB%B6%88%EC%9D%BC%EC%B9%98%22%20--%3E%20Deny3%5B%22%EC%A0%91%EA%B7%BC%20%EA%B1%B0%EC%A0%88%20%EB%B0%8F%20%EB%B3%B4%EC%95%88%20%EA%B0%90%EC%82%AC%20%EB%A1%9C%EA%B7%B8%20%EA%B8%B0%EB%A1%9D%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<hr><h2 id="_2-abac-속성-인벤토리-attribute-inventory" tabindex="-1">2. ABAC 속성 인벤토리 (Attribute Inventory) <a class="header-anchor" href="#_2-abac-속성-인벤토리-attribute-inventory" aria-label="Permalink to “2. ABAC 속성 인벤토리 (Attribute Inventory)”">​</a></h2><p>권한 평가는 정규화된 3가지 범주의 속성을 조합하여 수행됩니다.</p><h3 id="_1-주체-속성-subject-attributes" tabindex="-1">1) 주체 속성 (Subject Attributes) <a class="header-anchor" href="#_1-주체-속성-subject-attributes" aria-label="Permalink to “1) 주체 속성 (Subject Attributes)”">​</a></h3><ul><li><code>userId / username</code>: 요청자 고유 식별자</li><li><code>tenantId / orgId</code>: 다중 테넌트 및 소속 부서 식별자</li><li><code>roles / permissions</code>: 기존 RBAC 체계에서 부여된 권한 집합</li><li><code>agentToken</code>: 내부 시스템 에이전트 통신용 서명 및 인증 토큰 (<code>Signed Header</code>)</li></ul><h3 id="_2-자원-속성-resource-attributes" tabindex="-1">2) 자원 속성 (Resource Attributes) <a class="header-anchor" href="#_2-자원-속성-resource-attributes" aria-label="Permalink to “2) 자원 속성 (Resource Attributes)”">​</a></h3><ul><li><code>resourceId / ownerId</code>: 수집 데이터의 고유 키 및 소유자 식별자</li><li><code>resourceType</code>: 접근 대상 객체 유형 (예: <code>CrawledDataset</code>, <code>Scenario</code>, <code>Credential</code>)</li><li><code>sensitivityClassification</code>: 데이터의 보안 등급 (<code>PUBLIC</code>, <code>INTERNAL</code>, <code>RESTRICTED</code>)</li></ul><h3 id="_3-환경-속성-environment-attributes" tabindex="-1">3) 환경 속성 (Environment Attributes) <a class="header-anchor" href="#_3-환경-속성-environment-attributes" aria-label="Permalink to “3) 환경 속성 (Environment Attributes)”">​</a></h3><ul><li><code>networkLocation</code>: 내부 VPC/AKS 클러스터 내부 통신인지, 공용 인터넷 게이트웨이 유입인지 여부</li><li><code>endpointType</code>: 호출된 URI의 용도 (<code>INTERNAL_SYSTEM_API</code> vs <code>EXTERNAL_CLIENT_API</code>)</li></ul><hr><h2 id="_3-정책-평가-3단계-우선순위-policy-precedence" tabindex="-1">3. 정책 평가 3단계 우선순위 (Policy Precedence) <a class="header-anchor" href="#_3-정책-평가-3단계-우선순위-policy-precedence" aria-label="Permalink to “3. 정책 평가 3단계 우선순위 (Policy Precedence)”">​</a></h2><p>권한 검사는 단일화된 <code>AuthorizationContext</code> 내에서 사전에 정의된 엄격한 순서(Precedence)에 따라 순차 평가됩니다.</p><ol><li><strong>1단계: 환경 게이트 (Deny-first)</strong>: <ul><li>내부 에이전트 전용 엔드포인트(예: <code>/api/internal/worker/*</code>)에 퍼블릭 인그레스를 통한 외부 접근이 감지되면 즉시 차단합니다.</li></ul></li><li><strong>2단계: 대분류 RBAC 검사</strong>: <ul><li>요청 주체가 해당 도메인의 기본 권한(예: <code>@PreAuthorize(&quot;hasPermission(&#39;crawling:read&#39;)&quot;)</code>)을 보유하고 있는지 검증합니다.</li></ul></li><li><strong>3단계: 세부 ABAC 및 데이터 권한 검사 (Allow-only)</strong>: <ul><li>요청 주체의 <code>tenantId</code>와 자원의 테넌트 소속이 일치하는지 확인합니다.</li><li>자원의 보안 등급이 <code>RESTRICTED</code>인 경우 주체의 인가 등급과 자원 소유자(<code>ownerId</code>) 일치 여부를 최종 대조하여 단일 조건이라도 위배되면 접근을 거부합니다.</li></ul></li></ol><hr><h2 id="_4-내부-에이전트-토큰-인증-및-감사-추적" tabindex="-1">4. 내부 에이전트 토큰 인증 및 감사 추적 <a class="header-anchor" href="#_4-내부-에이전트-토큰-인증-및-감사-추적" aria-label="Permalink to “4. 내부 에이전트 토큰 인증 및 감사 추적”">​</a></h2><ul><li><strong>Signed Header 검증</strong>: <ul><li>분산 워커 에이전트(<code>smart-crawling-agent</code>)가 중앙 서버로 수집 데이터를 전송할 때, 타임스탬프와 비밀 키로 서명된 <code>X-Sync-Agent-Token</code> 헤더를 첨부합니다.</li></ul></li><li><strong>재전송 공격 방지</strong>: <ul><li>서명된 토큰의 유효 시간은 60초로 제한되며, 동일한 서명 토큰의 재사용 시도는 서버 메모리 윈도우에서 즉각 차단됩니다.</li></ul></li><li><strong>보안 감사 리포트 연계</strong>: <ul><li>모든 권한 평가 성공 및 실패 내역은 비인가 접근 시도 IP와 주체 식별자를 포함하여 WORM 감사 로그에 기록되어 보안 컴플라이언스 증적으로 활용됩니다.</li></ul></li></ul>',16))])}const m=i(d,[["render",s]]);export{p as __pageData,m as default};
